import { forwardRef, useState } from 'react'
import { type TamaguiElement, isWeb } from 'tamagui'
import { useControllableState } from '../../hooks/useControllableState'
import { useFieldControl } from '../../hooks/useFieldControl'
import { Chip } from '../chip/Chip'
import { ComboboxField } from '../combobox/ComboboxField'
import type { ComboboxFieldProps } from '../combobox/options'

export interface MultiSelectProps extends Omit<
  ComboboxFieldProps,
  | 'selected'
  | 'multiple'
  | 'inputValue'
  | 'onInputValueChange'
  | 'query'
  | 'onPick'
  | 'onClose'
  | 'leading'
  | 'onBackspaceEmpty'
> {
  value?: string[]
  defaultValue?: string[]
  onValueChange?: (value: string[]) => void
  /** Accessible name of each chip's remove button. Default: "Remove {label}". */
  removeLabel?: (label: string) => string
}

const none: string[] = []

/**
 * Pick several options from a searchable list. Picks show as chips in the
 * field. On web it is a combobox with a multi-select listbox that stays open;
 * on phones it opens a bottom sheet of checkbox rows.
 */
export const MultiSelect = forwardRef<TamaguiElement, MultiSelectProps>(
  function MultiSelect(selectProps, ref) {
    const {
      value: valueProp,
      defaultValue = none,
      onValueChange,
      options,
      removeLabel = (label: string) => `Remove ${label}`,
      disabled = false,
      ...props
    } = useFieldControl(selectProps)
    const [value, setValue] = useControllableState({
      value: valueProp,
      defaultValue,
      onChange: onValueChange,
    })
    const [query, setQuery] = useState('')
    const remove = (item: string) => setValue(value.filter((v) => v !== item))
    const picked = value.map((v) => options.find((o) => o.value === v) ?? { value: v, label: v })

    return (
      <ComboboxField
        ref={ref}
        multiple
        options={options}
        selected={value}
        inputValue={query}
        query={query}
        onInputValueChange={setQuery}
        onPick={(option) => {
          setValue(
            value.includes(option.value)
              ? value.filter((v) => v !== option.value)
              : [...value, option.value],
          )
          setQuery('')
        }}
        onClose={() => setQuery('')}
        onBackspaceEmpty={() => value.length && remove(value[value.length - 1]!)}
        disabled={disabled}
        leading={picked.map((option) => (
          <Chip
            key={option.value}
            disabled={disabled}
            // On native the field is one button; chips there are labels, and
            // options are removed by unchecking them in the sheet.
            {...(isWeb && {
              onRemove: () => remove(option.value),
              removeLabel: removeLabel(option.label),
            })}
          >
            {option.label}
          </Chip>
        ))}
        {...props}
      />
    )
  },
)

import { CheckIcon, ChevronDownIcon, IconDefaults } from '@advui/icons'
import { autoUpdate, flip, offset, shift, size, useFloating } from '@tamagui/floating'
import { shadows, zIndex } from '@advui/theme'
import { forwardRef, useEffect, useId, useRef, useState } from 'react'
import {
  type GetProps,
  Input as TamaguiInput,
  Portal,
  type TamaguiElement,
  View,
  XStack,
  styled,
} from 'tamagui'
import { useFieldControl } from '../../hooks/useFieldControl'
import { fieldBoxStyle } from '../input/Input'
import { Text } from '../typography/Text'
import { type ComboboxFieldProps, defaultFilter, fieldHeights } from './options'

const FieldBox = styled(XStack, {
  name: 'ComboboxField',
  ...fieldBoxStyle,
  alignItems: 'center',
  flexWrap: 'wrap',
  gap: '$1.5',
  cursor: 'text',
  // The input inside draws no ring of its own; the box shows focus instead.
  focusWithinStyle: {
    borderColor: '$ring',
    outlineColor: '$ring',
    outlineStyle: 'solid',
    outlineWidth: 2,
    outlineOffset: 0,
  },

  variants: {
    size: {
      sm: { minHeight: '$8', paddingHorizontal: '$2.5', paddingVertical: '$0.5' },
      md: { minHeight: '$10', paddingHorizontal: '$3', paddingVertical: '$1' },
      lg: { minHeight: '$12', paddingHorizontal: '$4', paddingVertical: '$1' },
    },
    invalid: {
      true: {
        borderColor: '$error',
        hoverStyle: { borderColor: '$error' },
        focusWithinStyle: { borderColor: '$error', outlineColor: '$error' },
      },
    },
    disabled: {
      true: { opacity: 0.5, cursor: 'not-allowed', pointerEvents: 'none' },
    },
  } as const,

  defaultVariants: { size: 'md' },
})

const BareInput = styled(TamaguiInput, {
  name: 'ComboboxInput',
  unstyled: true,
  flex: 1,
  minWidth: '$16',
  padding: 0,
  borderWidth: 0,
  backgroundColor: 'transparent',
  fontFamily: '$body',
  fontSize: '$2',
  color: '$foreground',
  placeholderTextColor: '$placeholderColor',
  // The field box draws the focus ring; `outline-style: auto` ignores width.
  outlineStyle: 'none',
  focusStyle: { outlineStyle: 'none' },
  focusVisibleStyle: { outlineStyle: 'none' },
})

const ListFrame = styled(View, {
  name: 'ComboboxList',
  backgroundColor: '$popover',
  borderWidth: 1,
  borderColor: '$border',
  borderRadius: '$lg',
  padding: '$1',
  overflow: 'scroll',
  ...shadows.md,
})

const OptionRow = styled(XStack, {
  name: 'ComboboxOption',
  alignItems: 'center',
  gap: '$2',
  minHeight: '$8',
  paddingHorizontal: '$2',
  paddingVertical: '$1.5',
  borderRadius: '$md',
  cursor: 'pointer',

  variants: {
    highlighted: { true: { backgroundColor: '$accent' } },
    disabled: { true: { opacity: 0.5, cursor: 'not-allowed' } },
  } as const,
})

type KeyEvent = { key: string; preventDefault: () => void }

/**
 * The web field behind Combobox, Autocomplete and Multi Select: a text box
 * with `role="combobox"` and a listbox that floats below it. Focus never
 * leaves the text box; `aria-activedescendant` points at the highlighted
 * option (the WAI-ARIA combobox pattern with list autocomplete).
 */
export const ComboboxField = forwardRef<TamaguiElement, ComboboxFieldProps>(
  function ComboboxField(fieldProps, ref) {
    const {
      options,
      selected,
      multiple = false,
      inputValue,
      onInputValueChange,
      query,
      filter = defaultFilter,
      onPick,
      onClose,
      leading,
      onBackspaceEmpty,
      emptyText = 'No results',
      placeholder,
      size: sizeProp = 'md',
      invalid = false,
      disabled = false,
      id,
      'aria-label': ariaLabel,
      'aria-describedby': describedBy,
      'aria-required': required,
      width = '100%',
    } = useFieldControl(fieldProps)
    const listId = useId()
    const optionId = (index: number) => `${listId}-${index}`
    const [open, setOpenState] = useState(false)
    const [active, setActive] = useState(-1)
    const inputRef = useRef<HTMLInputElement | null>(null)

    const matches = query ? options.filter((option) => filter(option, query)) : options
    const showList = open && (matches.length > 0 || emptyText !== null)

    const setOpen = (next: boolean) => {
      if (next === open) return
      setOpenState(next)
      if (!next) {
        setActive(-1)
        onClose?.()
      }
    }

    const { refs, floatingStyles } = useFloating({
      open: showList,
      placement: 'bottom-start',
      strategy: 'fixed',
      whileElementsMounted: autoUpdate,
      middleware: [
        offset(4),
        flip({ padding: 8 }),
        shift({ padding: 8 }),
        size({
          padding: 8,
          apply({ rects, availableHeight, elements }) {
            Object.assign(elements.floating.style, {
              width: `${rects.reference.width}px`,
              maxHeight: `${Math.min(availableHeight, 288)}px`,
            })
          },
        }),
      ],
    })

    // Keep the highlighted option in view while arrowing through a long list.
    useEffect(() => {
      if (active < 0) return
      document.getElementById(`${listId}-${active}`)?.scrollIntoView({ block: 'nearest' })
    }, [active, listId])

    // New matches start from the first one.
    const matchCount = matches.length
    useEffect(() => setActive(query && matchCount ? 0 : -1), [query, matchCount])

    const move = (step: 1 | -1) => {
      if (!open) return setOpen(true)
      if (matches.length === 0) return
      let next = active
      for (let i = 0; i < matches.length; i++) {
        next = (next + step + matches.length) % matches.length
        if (!matches[next]!.disabled) break
      }
      setActive(next)
    }

    const pick = (index: number) => {
      const option = matches[index]
      if (!option || option.disabled) return
      onPick(option)
      if (!multiple) setOpen(false)
    }

    const onKeyDown = (event: KeyEvent) => {
      switch (event.key) {
        case 'ArrowDown':
          event.preventDefault()
          return move(1)
        case 'ArrowUp':
          event.preventDefault()
          return move(-1)
        case 'Enter':
          if (open && active >= 0) {
            event.preventDefault()
            pick(active)
          }
          return
        case 'Escape':
          if (open) {
            event.preventDefault()
            setOpen(false)
          }
          return
        case 'Backspace':
          if (!inputValue) onBackspaceEmpty?.()
          return
      }
    }

    return (
      <>
        <FieldBox
          ref={(node: TamaguiElement | null) => {
            refs.setReference(node as unknown as Element | null)
            if (typeof ref === 'function') ref(node)
            else if (ref) ref.current = node
          }}
          size={sizeProp}
          invalid={invalid}
          disabled={disabled}
          width={width as GetProps<typeof FieldBox>['width']}
          onPress={() => inputRef.current?.focus()}
        >
          {leading}
          <BareInput
            ref={inputRef as never}
            id={id}
            role="combobox"
            aria-label={ariaLabel}
            aria-describedby={describedBy}
            aria-required={required}
            aria-invalid={invalid || undefined}
            aria-expanded={showList}
            aria-controls={listId}
            aria-autocomplete="list"
            aria-activedescendant={showList && active >= 0 ? optionId(active) : undefined}
            autoComplete="off"
            autoCorrect={false}
            spellCheck={false}
            disabled={disabled}
            placeholder={placeholder}
            height={fieldHeights[sizeProp]}
            value={inputValue}
            onChangeText={(text) => {
              onInputValueChange(text)
              setOpen(true)
            }}
            onKeyDown={onKeyDown as never}
            onBlur={() => setOpen(false)}
          />
          <View
            aria-hidden
            padding="$1"
            cursor="pointer"
            onPress={() => {
              inputRef.current?.focus()
              setOpen(!open)
            }}
          >
            <ChevronDownIcon size={16} color="$mutedForeground" />
          </View>
        </FieldBox>
        {showList ? (
          <Portal zIndex={zIndex.popover}>
            <ListFrame
              ref={refs.setFloating as never}
              id={listId}
              role={'listbox' as never}
              aria-label={ariaLabel}
              aria-multiselectable={multiple || undefined}
              style={floatingStyles}
              // Keep focus in the text box when the list is clicked.
              onMouseDown={(event: { preventDefault: () => void }) => event.preventDefault()}
            >
              {matches.length === 0 ? (
                <Text size="sm" tone="muted" padding="$2">
                  {emptyText}
                </Text>
              ) : (
                matches.map((option, index) => {
                  const isSelected = selected.includes(option.value)
                  return (
                    <OptionRow
                      key={option.value}
                      id={optionId(index)}
                      role={'option' as never}
                      aria-selected={isSelected}
                      aria-disabled={option.disabled || undefined}
                      highlighted={index === active}
                      disabled={option.disabled}
                      onMouseEnter={() => {
                        if (!option.disabled) setActive(index)
                      }}
                      onPress={() => pick(index)}
                    >
                      <View width="$4" alignItems="center">
                        {isSelected ? (
                          <IconDefaults size={16} color="$popoverForeground">
                            <CheckIcon />
                          </IconDefaults>
                        ) : null}
                      </View>
                      <View flex={1}>
                        <Text size="sm" color="$popoverForeground">
                          {option.label}
                        </Text>
                        {option.description ? (
                          <Text size="xs" tone="muted">
                            {option.description}
                          </Text>
                        ) : null}
                      </View>
                    </OptionRow>
                  )
                })
              )}
            </ListFrame>
          </Portal>
        ) : null}
      </>
    )
  },
)

import { CheckIcon, ChevronDownIcon, IconDefaults } from '@advui/icons'
import { forwardRef, useState } from 'react'
import { Sheet, type TamaguiElement, View, XStack, styled } from 'tamagui'
import { useBackToClose } from '../../hooks/useBackToClose'
import { FieldContext, useFieldControl } from '../../hooks/useFieldControl'
import { useReducedMotion } from '../../hooks/useReducedMotion'
import { useRipple } from '../../hooks/useRipple'
import { fieldBoxStyle, Input } from '../input/Input'
import { Text } from '../typography/Text'
import { type ComboboxFieldProps, type ComboboxOption, defaultFilter } from './options'

const FieldBox = styled(XStack, {
  name: 'ComboboxField',
  ...fieldBoxStyle,
  alignItems: 'center',
  flexWrap: 'wrap',
  gap: '$1.5',

  variants: {
    size: {
      sm: { minHeight: '$8', paddingHorizontal: '$2.5', paddingVertical: '$0.5' },
      md: { minHeight: '$10', paddingHorizontal: '$3', paddingVertical: '$1' },
      lg: { minHeight: '$12', paddingHorizontal: '$4', paddingVertical: '$1' },
    },
    invalid: { true: { borderColor: '$error' } },
    disabled: { true: { opacity: 0.5 } },
  } as const,

  defaultVariants: { size: 'md' },
})

function OptionRow({
  option,
  selected,
  multiple,
  onPress,
}: {
  option: ComboboxOption
  selected: boolean
  multiple: boolean
  onPress: () => void
}) {
  const ripple = useRipple({ color: '$popoverForeground', disabled: option.disabled })
  return (
    <View
      role={multiple ? 'checkbox' : 'button'}
      accessible
      aria-label={option.label}
      aria-checked={multiple ? selected : undefined}
      aria-selected={multiple ? undefined : selected}
      aria-disabled={option.disabled || undefined}
      flexDirection="row"
      alignItems="center"
      gap="$3"
      minHeight="$12"
      paddingHorizontal="$3"
      borderRadius="$md"
      opacity={option.disabled ? 0.5 : 1}
      pressStyle={option.disabled || ripple.active ? undefined : { backgroundColor: '$accent' }}
      onPress={option.disabled ? undefined : onPress}
      accessibilityActions={[{ name: 'activate' }]}
      onAccessibilityAction={(event: { nativeEvent: { actionName: string } }) => {
        if (!option.disabled && event.nativeEvent.actionName === 'activate') onPress()
      }}
      {...ripple.props}
    >
      {ripple.element}
      <View width="$5" alignItems="center">
        {selected ? (
          <IconDefaults size={18} color="$popoverForeground">
            <CheckIcon />
          </IconDefaults>
        ) : null}
      </View>
      <View flex={1}>
        <Text color="$popoverForeground">{option.label}</Text>
        {option.description ? (
          <Text size="sm" tone="muted">
            {option.description}
          </Text>
        ) : null}
      </View>
    </View>
  )
}

/**
 * The iOS / Android field behind Combobox, Autocomplete and Multi Select: a
 * field-shaped button that opens a bottom sheet with a search box and large,
 * labelled rows. A floating list under a text box is hard to reach with a
 * screen reader and is covered by the keyboard on phones.
 */
export const ComboboxField = forwardRef<TamaguiElement, ComboboxFieldProps>(
  function ComboboxField(fieldProps, ref) {
    const {
      options,
      selected,
      multiple = false,
      inputValue,
      onInputValueChange,
      query,
      filter = defaultFilter,
      onPick,
      onClose,
      leading,
      emptyText = 'No results',
      placeholder,
      size = 'md',
      invalid = false,
      disabled = false,
      id,
      'aria-label': ariaLabel,
      accessibilityHint,
      title,
      autoFocusSearch = false,
      width = '100%',
    } = useFieldControl(fieldProps)
    const [open, setOpenState] = useState(false)
    const reducedMotion = useReducedMotion()
    const setOpen = (next: boolean) => {
      setOpenState(next)
      if (!next) onClose?.()
    }
    // Android: the back button closes the sheet instead of leaving the screen.
    useBackToClose(open, () => setOpen(false))

    const matches = query ? options.filter((option) => filter(option, query)) : options
    // Multi Select shows chips in the field; the others show the text.
    const summary = multiple ? null : inputValue

    return (
      <>
        <FieldBox
          ref={ref}
          id={id}
          role="button"
          accessible
          aria-label={ariaLabel}
          aria-disabled={disabled || undefined}
          accessibilityHint={accessibilityHint}
          accessibilityValue={{ text: multiple ? `${selected.length} selected` : inputValue }}
          size={size}
          invalid={invalid}
          disabled={disabled}
          width={width as never}
          onPress={disabled ? undefined : () => setOpen(true)}
        >
          {leading}
          <Text
            flex={1}
            size="sm"
            numberOfLines={1}
            color={summary ? '$foreground' : '$placeholderColor'}
          >
            {summary || (multiple && selected.length ? '' : placeholder)}
          </Text>
          <ChevronDownIcon size={16} color="$mutedForeground" />
        </FieldBox>
        {/* The sheet's search box is not the field's control. */}
        <FieldContext.Provider value={null}>
          <Sheet
            open={open}
            onOpenChange={setOpen}
            modal
            dismissOnSnapToBottom
            moveOnKeyboardChange
            snapPoints={[80]}
            transition={reducedMotion ? undefined : 'medium'}
          >
            <Sheet.Overlay
              backgroundColor="$overlay"
              enterStyle={{ opacity: 0 }}
              exitStyle={{ opacity: 0 }}
              transition={reducedMotion ? undefined : 'quick'}
            />
            <Sheet.Handle backgroundColor="$borderStrong" />
            <Sheet.Frame
              backgroundColor="$popover"
              borderTopLeftRadius="$dialog"
              borderTopRightRadius="$dialog"
              padding="$4"
              gap="$3"
            >
              {/* The sheet stays mounted while closed; hide it from screen readers until it opens. */}
              <View
                flex={1}
                gap="$3"
                aria-hidden={!open || undefined}
                accessibilityViewIsModal={open}
              >
                {title ? (
                  <Text weight="semibold" role="heading">
                    {title}
                  </Text>
                ) : null}
                <Input
                  aria-label={title ?? ariaLabel ?? 'Search'}
                  placeholder={placeholder}
                  // The search text only; the picked option is shown by its check.
                  value={query}
                  autoFocus={autoFocusSearch}
                  onChangeText={onInputValueChange}
                  autoCorrect={false}
                  autoCapitalize="none"
                />
                <Sheet.ScrollView keyboardShouldPersistTaps="handled">
                  {matches.length === 0 && emptyText ? (
                    <Text tone="muted" padding="$3">
                      {emptyText}
                    </Text>
                  ) : (
                    matches.map((option) => (
                      <OptionRow
                        key={option.value}
                        option={option}
                        multiple={multiple}
                        selected={selected.includes(option.value)}
                        onPress={() => {
                          onPick(option)
                          if (!multiple) setOpen(false)
                        }}
                      />
                    ))
                  )}
                </Sheet.ScrollView>
              </View>
            </Sheet.Frame>
          </Sheet>
        </FieldContext.Provider>
      </>
    )
  },
)

import type { ReactNode } from 'react'

export interface ComboboxOption {
  value: string
  label: string
  /** Second line under the label. */
  description?: string
  disabled?: boolean
}

export type ComboboxFilter = (option: ComboboxOption, query: string) => boolean

/** Case- and accent-insensitive "contains" on the label. */
export const defaultFilter: ComboboxFilter = (option, query) =>
  normalize(option.label).includes(normalize(query))

function normalize(text: string) {
  return text
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '')
    .toLowerCase()
    .trim()
}

/**
 * Everything Combobox, Autocomplete and Multi Select tell the shared field.
 * The field owns only open state and the highlighted option.
 */
export interface ComboboxFieldProps {
  options: ComboboxOption[]
  /** Values shown as selected (checked) in the list. */
  selected: string[]
  /** Several values: the list stays open after a pick and shows checkboxes. */
  multiple?: boolean
  /** Text in the input. */
  inputValue: string
  onInputValueChange: (text: string) => void
  /** Text the options are filtered by ('' shows every option). */
  query: string
  filter?: ComboboxFilter
  onPick: (option: ComboboxOption) => void
  /** Called when the list closes (blur, Escape, a pick in single mode). */
  onClose?: () => void
  /** Chips or other content before the input (Multi Select). */
  leading?: ReactNode
  /** Backspace in an empty input (Multi Select removes the last chip). */
  onBackspaceEmpty?: () => void
  /** Shown when nothing matches; null hides the list instead. */
  emptyText?: string | null
  placeholder?: string
  size?: 'sm' | 'md' | 'lg'
  invalid?: boolean
  disabled?: boolean
  id?: string
  'aria-label'?: string
  'aria-describedby'?: string
  'aria-required'?: boolean
  accessibilityHint?: string
  /** Phones: focus the sheet's search box as it opens (Autocomplete). */
  autoFocusSearch?: boolean
  /** Title of the sheet on phones. */
  title?: string
  width?: number | string
}

export const fieldHeights = { sm: '$8', md: '$10', lg: '$12' } as const

import { CheckIcon, IconDefaults, XIcon } from '@advui/icons'
import { type ReactNode, forwardRef } from 'react'
import { type GetProps, type TamaguiElement, Text, View, isWeb, styled } from 'tamagui'
import { useControllableState } from '../../hooks/useControllableState'
import { useRipple } from '../../hooks/useRipple'
import { isTextContent } from '../../utils/isTextContent'

const ChipFrame = styled(View, {
  name: 'Chip',
  flexDirection: 'row',
  alignItems: 'center',
  alignSelf: 'flex-start',
  gap: '$1.5',
  height: '$8',
  paddingHorizontal: '$3',
  borderWidth: 1,
  borderColor: '$input',
  borderRadius: '$lg',
  backgroundColor: 'transparent',
  userSelect: 'none',

  variants: {
    interactive: {
      true: {
        cursor: 'pointer',
        hoverStyle: { backgroundColor: '$accent' },
        pressStyle: { backgroundColor: '$accentHover' },
        focusVisibleStyle: {
          outlineColor: '$ring',
          outlineStyle: 'solid',
          outlineWidth: 2,
          outlineOffset: 2,
        },
      },
    },
    // Material's selected filter chip: a filled tonal surface without a border.
    selected: {
      true: {
        backgroundColor: '$secondary',
        borderColor: '$secondary',
        hoverStyle: { backgroundColor: '$secondaryHover' },
        pressStyle: { backgroundColor: '$secondaryPress' },
      },
    },
    disabled: {
      true: { opacity: 0.5, pointerEvents: 'none', cursor: 'default' },
    },
  } as const,
})

type FrameProps = GetProps<typeof ChipFrame>

export interface ChipProps extends Omit<
  FrameProps,
  'interactive' | 'selected' | 'disabled' | 'children'
> {
  children: ReactNode
  /** Leading icon. A selected filter chip shows a check instead. */
  icon?: ReactNode
  /**
   * Makes it a filter chip that turns on and off (announced as pressed). Use
   * `defaultSelected` for uncontrolled use.
   */
  selected?: boolean
  defaultSelected?: boolean
  onSelectedChange?: (selected: boolean) => void
  /** Makes it an input chip with a remove button, e.g. a recipient. */
  onRemove?: () => void
  /** Accessible name of the remove button. Default: "Remove {children}". */
  removeLabel?: string
  disabled?: boolean
}

type LabelColor = '$foreground' | '$secondaryForeground'

const Label = ({ children, color }: { children: ReactNode; color: LabelColor }) =>
  isTextContent(children) ? (
    <Text
      fontFamily="$body"
      fontSize="$2"
      lineHeight="$2"
      fontWeight="500"
      color={color}
      numberOfLines={1}
      userSelect="none"
    >
      {children}
    </Text>
  ) : (
    <>{children}</>
  )

/**
 * A compact element for a choice, a filter, an entered value or a suggested
 * action. Pass `selected` for a filter chip, `onRemove` for an input chip or
 * `onPress` for an action chip.
 */
export const Chip = forwardRef<TamaguiElement, ChipProps>(function Chip(
  {
    children,
    icon,
    selected: selectedProp,
    defaultSelected,
    onSelectedChange,
    onRemove,
    removeLabel,
    disabled = false,
    onPress,
    onPressIn,
    onPressOut,
    ...props
  },
  ref,
) {
  const filter =
    selectedProp !== undefined || defaultSelected !== undefined || onSelectedChange !== undefined
  const [selected, setSelected] = useControllableState({
    value: selectedProp,
    defaultValue: defaultSelected ?? false,
    onChange: onSelectedChange,
  })
  const on = filter && selected
  const color: LabelColor = on ? '$secondaryForeground' : '$foreground'
  const leading = on ? <CheckIcon /> : icon
  const pressable = filter || onPress !== undefined
  const ripple = useRipple({ color, disabled: disabled || !pressable, onPressIn, onPressOut })
  const removeRipple = useRipple({
    color: '$mutedForeground',
    disabled: disabled || !onRemove || filter,
  })

  // An input chip is a group: its text plus a separate remove button, so the
  // remove action has its own name and focus stop.
  if (onRemove && !filter) {
    const name = removeLabel ?? (typeof children === 'string' ? `Remove ${children}` : 'Remove')
    return (
      <ChipFrame ref={ref} paddingRight="$1" disabled={disabled} {...props} {...ripple.props}>
        <IconDefaults size={18} color="$mutedForeground">
          {icon}
        </IconDefaults>
        <Label color="$foreground">{children}</Label>
        <View
          render="button"
          role="button"
          aria-label={name}
          alignItems="center"
          justifyContent="center"
          width="$6"
          height="$6"
          borderRadius="$full"
          cursor="pointer"
          hoverStyle={{ backgroundColor: '$accent' }}
          pressStyle={removeRipple.active ? undefined : { backgroundColor: '$accentHover' }}
          focusVisibleStyle={{ outlineColor: '$ring', outlineStyle: 'solid', outlineWidth: 2 }}
          {...(isWeb
            ? { type: 'button', padding: 0, borderWidth: 0, backgroundColor: 'transparent' }
            : { accessible: true, hitSlop: 10 })}
          onPress={() => !disabled && onRemove()}
          {...removeRipple.props}
        >
          {removeRipple.element}
          <XIcon size={14} color="$mutedForeground" />
        </View>
      </ChipFrame>
    )
  }

  const semantics = !pressable
    ? {}
    : isWeb
      ? {
          render: 'button' as const,
          type: 'button',
          tabIndex: 0,
          'aria-pressed': filter ? on : undefined,
        }
      : filter
        ? {
            // React Native has no aria-pressed; a toggle button reports "checked".
            accessible: true,
            accessibilityRole: 'togglebutton' as const,
            accessibilityState: { checked: on, disabled },
            hitSlop: 6,
          }
        : { accessible: true, role: 'button' as const, hitSlop: 6 }

  return (
    <ChipFrame
      ref={ref}
      interactive={pressable}
      selected={on}
      disabled={disabled}
      aria-disabled={disabled || undefined}
      {...semantics}
      onPress={
        pressable
          ? (event) => {
              if (disabled) return
              onPress?.(event)
              if (filter) setSelected(!selected)
            }
          : undefined
      }
      {...(ripple.active && {
        pressStyle: { backgroundColor: on ? '$secondary' : 'transparent' },
        // The ripple is clipped inside the border; a selected chip's border
        // matches its fill, so drop it and let the ripple reach the edge.
        ...(on && { borderWidth: 0 }),
      })}
      {...props}
      {...ripple.props}
    >
      {ripple.element}
      <IconDefaults size={18} color={on ? '$secondaryForeground' : '$mutedForeground'}>
        {leading}
      </IconDefaults>
      <Label color={color}>{children}</Label>
    </ChipFrame>
  )
})

